/**
 * Parity CM snapshot (READ-ONLY). Emits one JSONL line per re-accreditation work item, then a trailer.
 *
 *   mongosh "<cm connection string incl. database>" --quiet cm-snapshot.js > cm.jsonl
 *
 * Optional: --eval "PARITY_DB='name'; undefined" to override the database.
 * Optional submission window on submittedAt, half-open [start, end), ISO-8601 (UTC if no offset), either bound optional:
 *   --eval "PARITY_START='2026-10-01T00:00:00Z'; PARITY_END='2026-11-01T00:00:00Z'; undefined"
 * GENERATED by build.mjs - edit src/, not this file.
 */
const TARGET_DB = typeof PARITY_DB !== 'undefined' && PARITY_DB ? PARITY_DB : db.getName()
const collection = db.getSiblingDB(TARGET_DB).getCollection('workItems')
installReadOnlyGuard(collection, 'cm-snapshot')

const takenAt = new Date().toISOString()

function uuidStr(v) {
  if (v === undefined || v === null) return null
  if (typeof v.toUUID === 'function') return v.toUUID().toString().replace(/^UUID\("?|"?\)$/g, '')
  return idStr(v)
}

// Small audit summary so the full audit log is never exported.
function auditBlock(item) {
  const log = Array.isArray(item.auditLog) ? item.auditLog : []
  const queries = log.filter((e) => e.action === 'application-queried')
  const lastQuery = queries.length ? queries[queries.length - 1] : null
  const sites = item.payload && item.payload.overseasSites && item.payload.overseasSites.sites
  return {
    lastQueryAction: lastQuery && lastQuery.details ? nz(lastQuery.details.actionId) : null,
    lastQueryAt: lastQuery ? iso(lastQuery.createdAt) : null,
    queryRespondedAt: log.filter((e) => e.action === 'query-responded').map((e) => iso(e.createdAt)),
    // CM stamps recyclingOperationsUpdatedAt on the payload site when a user edits the codes.
    hasRecyclingOpsUpdate:
      (Array.isArray(sites) && sites.some((s) => nz(s.recyclingOperationsUpdatedAt) !== null)) ||
      log.some((e) => typeof e.action === 'string' && e.action.indexOf('recycling') !== -1),
    statusPushFailed: log.some((e) => e.action === 'status-push-failed')
  }
}

const win = parseWindow(
  typeof PARITY_START !== 'undefined' ? PARITY_START : null,
  typeof PARITY_END !== 'undefined' ? PARITY_END : null
)
// Only work items submitted from OJ: those carry the OJ application id in the payload. Items created any other way
// (seed/legacy/manual, empty or missing operatorApplicationId) are out of scope. The window applies to submittedAt.
const cmFilter = Object.assign(
  { typeId: 're-accreditation', 'payload.operatorApplicationId': { $nin: [null, ''] } },
  rangeClause('submittedAt', win)
)

let count = 0
const cursor = collection
  .find(
    cmFilter,
    {
      typeId: 1, stateId: 1, submittedAt: 1, lastModifiedAt: 1,
      'auditLog.action': 1, 'auditLog.createdAt': 1, 'auditLog.details.actionId': 1,
      payload: 1
    }
  )
  .readPref('secondaryPreferred')
  .batchSize(500)
while (cursor.hasNext()) {
  const item = cursor.next()
  const p = item.payload || {}
  const record = {
    snapshot: { service: 'CM', takenAt, db: TARGET_DB, scriptVersion: SCRIPT_VERSION },
    key: { applicationId: idStr(p.operatorApplicationId), workItemId: uuidStr(item._id) },
    identity: {
      applicationReference: nz(p.applicationReference),
      registrationNumber: nz(p.registrationNumber),
      accreditationNumber: nz(p.accreditationNumber) !== null ? nz(p.accreditationNumber) : nz(p.accreditationId),
      organisationName: nz(p.organisationName),
      orgNumber: nz(p.operatorOrgNumber),
      material: nz(p.material) === null ? null : String(p.material).toLowerCase(),
      year: nz(p.accreditationYear),
      isExporter: null
    },
    state: { raw: nz(item.stateId), normalised: nz(item.stateId), updatedAt: iso(item.lastModifiedAt) },
    audit: auditBlock(item),
    sections: normaliseSections(p)
  }
  print(JSON.stringify(record))
  count++
}
print(JSON.stringify({
  trailer: true, service: 'CM', count, takenAt, scriptVersion: SCRIPT_VERSION,
  window: { start: iso(win.start), end: iso(win.end) }
}))
